import org.eclipse.core.runtime.CoreException;
import org.eclipse.core.runtime.IProgressMonitor;

class Example {
    private FileManager fManager = new FileManager();

    void commitFileBufferContent(IProgressMonitor monitor, boolean overwrite) throws CoreException {
        // dummy implementation
        if (Math.random() < 0.5) throw new CoreException(null);
        if (Math.random() < 0.5) throw new RuntimeException();
    }

    void someMethod(IProgressMonitor monitor, boolean overwrite) {
        try {
            commitFileBufferContent(monitor, overwrite);
        } catch (CoreException x) {
            fManager.fireStateChangeFailed(this);
            throw x;
        } catch (RuntimeException x) {
            fManager.fireStateChangeFailed(this);
            throw x;
        }
    }

    static class FileManager {
        void fireStateChangeFailed(Object buffer) { System.err.println("State change failed for " + buffer); }
    }
}

